style.css:
@-moz-document url-prefix("https://www.google.") {
/* Taustakuva koko sivulle */
  body, html {
    background: url("https://i.pinimg.com/736x/8a/b2/85/8ab28530a0338c241619c4888368f264.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Poistetaan alkuperäinen valkoinen tausta */
  #viewport, #main, .LgbsSe, .o3j99 {
    background: transparent !important;
  }

  /* Hakukentän tausta tummanvihreäksi */
  input[name="q"] {
    background-color: #013220 !important; /* Tummanvihreä */
    color: white !important;
    border: 1px solid #0f3d25 !important;
  }

  /* Hakukentän placeholder-teksti */
  input[name="q"]::placeholder {
    color: #cdeac0 !important;
  }

  /* Hakupainikkeet */
  input[type="submit"], .gNO89b, .RNmpXc {
    background-color: #014421 !important;
    color: white !important;
    border: none !important;
  }

  /* Tekstiä näkyvämmäksi tummalla taustalla */
  * {
    color: white !important;
  }
}
